import React, { useState, useRef, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';

interface ManualCropperProps {
  imageSrc: string;
  photoSize: PhotoSize;
  onCancel: () => void;
  onConfirm: (croppedImage: string) => void;
}

const ManualCropper: React.FC<ManualCropperProps> = ({ imageSrc, photoSize, onCancel, onConfirm }) => {
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0); // Any degree: -180 to 180 or more
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [imgDimensions, setImgDimensions] = useState({ w: 0, h: 0 });

  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);

  // Calculate Aspect Ratio
  const getAspectRatio = () => {
    switch (photoSize) {
      case PhotoSize.SIZE_3X4: return 3 / 4;
      case PhotoSize.SIZE_5X5: return 1;
      case PhotoSize.SIZE_4X6: 
      default: return 2 / 3; // 4x6 = 2/3
    }
  };

  const ASPECT_RATIO = getAspectRatio();

  // Load image dimensions
  const onImgLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
    setImgDimensions({ w: e.currentTarget.naturalWidth, h: e.currentTarget.naturalHeight });
  };

  // --- MOUSE / TOUCH EVENTS FOR PANNING ---
  const handleStart = (clientX: number, clientY: number) => {
    setIsDragging(true);
    setDragStart({ x: clientX - offset.x, y: clientY - offset.y });
  };

  const handleMove = (clientX: number, clientY: number) => {
    if (!isDragging) return;
    setOffset({
      x: clientX - dragStart.x,
      y: clientY - dragStart.y
    });
  };

  const handleEnd = () => {
    setIsDragging(false);
  };

  // Mouse
  const onMouseDown = (e: React.MouseEvent) => handleStart(e.clientX, e.clientY);
  const onMouseMove = (e: React.MouseEvent) => handleMove(e.clientX, e.clientY);

  // Touch
  const onTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 1) handleStart(e.touches[0].clientX, e.touches[0].clientY);
  };
  const onTouchMove = (e: React.TouchEvent) => {
    if (e.touches.length === 1) handleMove(e.touches[0].clientX, e.touches[0].clientY);
  };

  // --- ROTATION HANDLERS ---
  const resetRotation = () => setRotation(0);

  // --- CROP LOGIC ---
  const handleCrop = async () => {
    if (!imgRef.current || !containerRef.current) return;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const cropBox = containerRef.current.querySelector('#crop-box')?.getBoundingClientRect();
    const imgRect = imgRef.current.getBoundingClientRect();

    if (!cropBox) return;

    // We want high resolution, so we base the canvas size on the crop box 
    // but relative to the image's natural resolution.
    const displayedImgW = imgRect.width;
    const displayedImgH = imgRect.height;

    // Scale between displayed size and natural size
    // Note: The displayed width of the img element changes with rotation, 
    // but getBoundingClientRect gives us the actual rendered box.
    // We need to calculate the scale based on the original un-rotated width.
    const scale = imgRef.current.naturalWidth / (displayedImgW / zoom);

    canvas.width = cropBox.width * scale;
    canvas.height = cropBox.height * scale;

    ctx.save();

    // 1. Move to the center of the canvas
    ctx.translate(canvas.width / 2, canvas.height / 2);

    // 2. Apply the rotation
    ctx.rotate((rotation * Math.PI) / 180);

    // 3. Calculate the position of the image center relative to the crop box center
    const cropBoxCenterX = cropBox.left + cropBox.width / 2;
    const cropBoxCenterY = cropBox.top + cropBox.height / 2;

    // We need to find the image center. 
    // Since we applied CSS transform: translate(offset.x, offset.y), the center of the image
    // is its original center + offset.
    // However, the CSS transform also includes rotation which affects getBoundingClientRect.
    // A more reliable way is to track the offset separately.

    // Displayed center point (relative to viewport)
    const containerRect = containerRef.current.getBoundingClientRect();
    const containerCenterX = containerRect.left + containerRect.width / 2;
    const containerCenterY = containerRect.top + containerRect.height / 2;

    const imgCenterX = containerCenterX + offset.x;
    const imgCenterY = containerCenterY + offset.y;

    const dx = (imgCenterX - cropBoxCenterX) * scale;
    const dy = (imgCenterY - cropBoxCenterY) * scale;

    // 4. Draw the image centered at the calculated offset
    // Apply zoom to the dimensions
    const drawW = imgRef.current.naturalWidth * zoom;
    const drawH = imgRef.current.naturalHeight * zoom;

    ctx.drawImage(
      imgRef.current,
      dx - (drawW / 2),
      dy - (drawH / 2),
      drawW,
      drawH
    );

    ctx.restore();

    onConfirm(canvas.toDataURL('image/png', 1.0));
  };

  return (
    <div className="absolute inset-0 z-50 bg-black flex flex-col">
      {/* Header */}
      <div className="flex justify-between items-center p-4 bg-black/50 backdrop-blur-md absolute top-0 left-0 right-0 z-20">
        <button onClick={onCancel} className="text-white font-bold text-sm px-4 py-2 rounded-full bg-white/10 hover:bg-white/20">
          Hủy
        </button>
        <span className="text-white font-black uppercase text-sm tracking-widest">CẮT & XOAY ẢNH</span>
        <button onClick={handleCrop} className="text-white font-bold text-sm px-6 py-2 rounded-full bg-brand-600 hover:bg-brand-500 shadow-lg shadow-brand-500/30">
          Xong
        </button>
      </div>

      {/* Workspace */}
      <div 
        className="flex-1 relative overflow-hidden flex items-center justify-center cursor-move touch-none bg-gray-900"
        ref={containerRef}
        onMouseDown={onMouseDown}
        onMouseMove={onMouseMove}
        onMouseUp={handleEnd}
        onMouseLeave={handleEnd}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={handleEnd}
      >
        {/* The Image */}
        <img 
          ref={imgRef}
          src={imageSrc} 
          onLoad={onImgLoad}
          alt="Crop source"
          className="absolute max-w-none origin-center transition-transform duration-75 ease-linear pointer-events-none select-none"
          style={{ 
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${zoom}) rotate(${rotation}deg)`,
            height: '60%', // Base height fit
          }}
          draggable={false}
        />

        {/* The Crop Box Overlay */}
        <div 
          id="crop-box"
          className="relative z-10 pointer-events-none border-2 border-white shadow-[0_0_0_9999px_rgba(0,0,0,0.7)]"
          style={{
            aspectRatio: `${ASPECT_RATIO}`,
            height: '65%', // Height relative to container
          }}
        >
           {/* Grid Lines */}
           <div className="absolute inset-0 grid grid-cols-3 grid-rows-3 opacity-30">
              <div className="border-r border-b border-white"></div>
              <div className="border-r border-b border-white"></div>
              <div className="border-b border-white"></div>
              <div className="border-r border-b border-white"></div>
              <div className="border-r border-b border-white"></div>
              <div className="border-b border-white"></div>
              <div className="border-r border-white"></div>
              <div className="border-r border-white"></div>
              <div></div>
           </div>

           {/* Info Tag */}
           <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-black/60 text-white text-[10px] px-2 py-1 rounded font-mono whitespace-nowrap">
              {photoSize}
           </div>
        </div>
      </div>

      {/* Footer Controls */}
      <div className="bg-gray-900 p-6 pb-safe border-t border-gray-800 z-20">
         <div className="max-w-md mx-auto space-y-5">

            {/* Zoom Slider */}
            <div className="space-y-2">
              <div className="flex justify-between text-[10px] font-black text-gray-400 uppercase tracking-widest items-center">
                 <span className="flex items-center gap-1">🔍 Thu phóng</span>
                 <span className="bg-gray-800 px-2 py-0.5 rounded text-white">{Math.round(zoom * 100)}%</span>
              </div>
              <input 
                type="range" 
                min="0.5" 
                max="4" 
                step="0.01" 
                value={zoom} 
                onChange={(e) => setZoom(parseFloat(e.target.value))} 
                className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-brand-500"
              />
            </div>

            {/* Rotation Slider (Fine Tuning) */}
            <div className="space-y-2">
              <div className="flex justify-between text-[10px] font-black text-gray-400 uppercase tracking-widest items-center">
                 <span className="flex items-center gap-1">🔄 Xoay chi tiết</span>
                 <button onClick={resetRotation} className="bg-gray-800 px-2 py-0.5 rounded text-white hover:text-brand-400 transition-colors">{rotation}° (Reset)</button>
              </div>
              <input 
                type="range" 
                min="-180" 
                max="180" 
                step="0.5" 
                value={rotation % 360} 
                onChange={(e) => setRotation(parseFloat(e.target.value))} 
                className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-brand-500"
              />
            </div>

            <p className="text-center text-[9px] text-gray-600 pt-2 uppercase tracking-tighter">
               Vuốt ảnh để di chuyển • Thanh trượt để zoom & xoay
            </p>
         </div>
      </div>
    </div>
  );
};

export default ManualCropper;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

// Schema cho phản hồi phân tích camera AI
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Phân tích frame webcam để kiểm tra độ tuân thủ ảnh thẻ bằng Gemini 3 Flash.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Phân tích ảnh thẻ sinh trắc học. Trả về JSON.
            Tiêu chí: Mặt nhìn thẳng, mắt mở, miệng đóng, đủ sáng, không bóng đổ mạnh.
            JSON: {isCompliant: boolean, status: 'VALID'|'ADJUSTING'|'INVALID', feedback: string, instruction: string, faceDetected: boolean}.
            'instruction': Câu lệnh tiếng Việt ngắn gọn (VD: "Nâng cằm lên", "Nhìn thẳng camera").` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Sẵn sàng', 
      faceDetected: true 
    };
  }
};

/**
 * Xử lý ảnh thẻ bằng AI.
 * ƯU TIÊN CAO NHẤT: THAY PHÔNG NỀN VÀ GIỮ NGUYÊN DANH TÍNH.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  bgHex: string | undefined,
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Các tham số cường độ làm đẹp (Scale an toàn)
  const contourSafe = Math.round((beautySettings.contourIntensity / 100) * 30);
  const blemishSafe = Math.round((beautySettings.blemishIntensity / 100) * 30);
  const eyebrowSafe = Math.round((beautySettings.eyebrowIntensity / 100) * 30);
  const eyelashSafe = Math.round((beautySettings.eyelashIntensity / 100) * 25);

  const isOriginalBg = bgType === BackgroundType.ORIGINAL;
  const targetBgColor = bgHex || (bgType === BackgroundType.BLUE ? '#2792ff' : '#ffffff');

  // Xây dựng hệ thống câu lệnh tập trung vào việc THAY ĐỔI NỀN
  const systemInstructions = [
    "You are a high-precision ID photo editor. Your PRIMARY mission is background replacement and professional grooming while keeping 100% identity accuracy.",
    "",
    "### TASK 1: MANDATORY BACKGROUND REPLACEMENT (CRITICAL)",
    isOriginalBg 
      ? "- KEEP the existing background exactly as it is. Do NOT change any pixels of the background." 
      : `- REMOVE the entire background behind the person.
- FILL the background with the EXACT solid color: ${targetBgColor}.
- The new background must be 100% uniform, flat, and solid. No shadows, no gradients, no textures.
- Even if the original background is already similar, you MUST replace every single background pixel with the exact HEX ${targetBgColor}.
- Mask edges (hair and clothes) must be clean and sharp without color bleeding.`,
    "",
    "### TASK 2: BIOMETRIC IDENTITY LOCK (ABSOLUTE RULES)",
    "- DO NOT change facial structure, bone shape, eyes, nose, mouth, chin, or any permanent features.",
    "- DO NOT remove identifying marks like moles or scars.",
    "- Keep facial dimensions and geometry 100% identical to the original image.",
    "",
    "### TASK 3: GROOMING & BEAUTY (BY INTENSITY)",
    `1. CLOTHING: ${clothingPrompt ? `Replace current clothing with: "${clothingPrompt}". Ensure the collar looks natural and formal.` : "Keep original clothing."}`,
    `2. SKIN SMOOTHING: Intensity ${beautySettings.smoothSkin}/100. Apply fixed smoothing without losing texture.`,
    `3. BLEMISH REMOVAL: Intensity ${blemishSafe}/100. Remove acne/temporary spots only.`,
    `4. MAKEUP: 
       - Lips: ${beautySettings.lipstickColor}, Intensity ${beautySettings.lipstickIntensity}/100.
       - Blush: ${beautySettings.blushColor}, Intensity ${beautySettings.blushIntensity}/100.
       - Eyebrows: Intensity ${eyebrowSafe}/100.
       - Eyelashes: Intensity ${eyelashSafe}/100.
       - Contour: Intensity ${contourSafe}/100.`,
    `5. HAIR: Color ${beautySettings.hairColor || "original"}, Volume Intensity ${beautySettings.hairVolume}/100.`,
    "",
